import React, { useState, useEffect } from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation,
  useNavigate
} from 'react-router-dom';

// IMPORTS CLIENT
import Home from './components/Clients/Home/Home';
import Contact from './components/Clients/Contact/Contact';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Services from './components/Clients/Services/Services';

// IMPORTS HEADER / FOOTER
import Header from './components/Clients/Widgets/Header/Header';
import Footer from './components/Clients/Widgets/Footer/Footer';

// IMPORTS AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// IMPORTS LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier session
  useEffect(() => {
    const userData = localStorage.getItem('userData');

    if (userData) {
      const user = JSON.parse(userData);
      setUserRole(user.role);
      setIsAuthenticated(true);

      if (user.role === 'admin' && !location.pathname.startsWith('/admin')) {
        navigate('/admin', { replace: true });
      }
    }

    setIsLoading(false);
  }, []);

  // Login
  const handleLogin = (userData) => {
    localStorage.setItem('userData', JSON.stringify(userData));
    setUserRole(userData.role);
    setIsAuthenticated(true);

    if (userData.role === 'admin') {
      navigate('/admin', { replace: true });
    } else {
      navigate('/dashboard', { replace: true });
    }
  };

  // Logout
  const handleLogout = () => {
    localStorage.removeItem('userData');
    setIsAuthenticated(false);
    setUserRole(null);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  // Masquer H/F pour dashboard admin et user
  const hideUi =
    userRole === 'admin' ||
    location.pathname.startsWith('/dashboard');

  return (
    <>
      {!hideUi && <Header isAuthenticated={isAuthenticated} onLogout={handleLogout} />}

      <Routes>

        {/* PAGES CLIENT (avec ClientLayout) */}
        <Route
          path="/"
          element={<ClientLayout><Home /></ClientLayout>}
        />
        <Route
          path="/contact"
          element={<ClientLayout><Contact /></ClientLayout>}
        />
        <Route
          path="/portfolio"
          element={<ClientLayout><Portfolio /></ClientLayout>}
        />
        <Route
          path="/services"
          element={<ClientLayout><Services /></ClientLayout>}
        />

        {/* LOGIN */}
        <Route
          path="/login"
          element={
            isAuthenticated ? (
              userRole === 'admin'
                ? <Navigate to="/admin" replace />
                : <Navigate to="/dashboard" replace />
            ) : (
              <Login onLogin={handleLogin} />
            )
          }
        />

        <Route path="/register" element={<Register />} />

        {/* DASHBOARD USER */}
        <Route
          path="/dashboard/*"
          element={
            <ProtectedRoute
              isAuthenticated={isAuthenticated}
              requiredRole="user"
              userRole={userRole}
            >
              <Dashboard onLogout={handleLogout} />
            </ProtectedRoute>
          }
        />

        {/* DASHBOARD ADMIN */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute
              isAuthenticated={isAuthenticated}
              requiredRole="admin"
              userRole={userRole}
            >
              <Dashboard onLogout={handleLogout} isAdmin={true} />
            </ProtectedRoute>
          }
        />

        {/* 404 */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      {!hideUi && <Footer />}
    </>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
